from duration import parse_duration


def test_seconds():
    assert parse_duration("45s") == 45


def test_minutes_and_seconds():
    assert parse_duration("2m30s") == 150


def test_hours_minutes_seconds():
    assert parse_duration("1h30m15s") == 5415

