import pytest

from duration import parse_duration


@pytest.mark.parametrize("h,m,s", [(0, 0, 7), (0, 5, 0), (3, 0, 0), (2, 45, 9), (10, 59, 59)])
def test_property_sum_of_components(h, m, s):
    text = f"{h}h{m}m{s}s"
    assert parse_duration(text) == h * 3600 + m * 60 + s


def test_repeated_unit_accumulates():
    assert parse_duration("1m1m") == 120
